            local Away = Origin - ThreatRoot.Position
            local AwayDirection = Vector3.new(Away.X, 0, Away.Z)
        
            if AwayDirection.Magnitude <= 0.01 then
                return nil
            end
        
            AwayDirection = AwayDirection.Unit
        
            --// Try several directions instead of blindly retreating straight back.
            --// This prevents Safe Distance from pushing the player into a wall,
            --// corner, or narrow gap when the direct retreat path is blocked.
            local Directions = {
                AwayDirection,
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(45)):VectorToWorldSpace(AwayDirection),
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(-45)):VectorToWorldSpace(AwayDirection),
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(90)):VectorToWorldSpace(AwayDirection),
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(-90)):VectorToWorldSpace(AwayDirection),
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(135)):VectorToWorldSpace(AwayDirection),
                CFrame.fromAxisAngle(Vector3.yAxis, math.rad(-135)):VectorToWorldSpace(AwayDirection),
            }
        
            local CurrentTargetDistance = AICCombatUtils.GetHorizontalDistance(Origin, TargetRoot.Position)
            local BestPosition = nil
            local BestScore = math.huge
        
            for Index, Direction in ipairs(Directions) do
                Direction = Vector3.new(Direction.X, 0, Direction.Z)
        
                if Direction.Magnitude <= 0.01 then
                    continue
                end
        
                Direction = Direction.Unit
        
                --// Prefer shorter movement when multiple escape directions are safe.
                local Candidate = Origin + Direction * CONFIG.THREAT_ESCAPE_DISTANCE
        
                if not AICCombatUtils.IsInsideFarmArea(Candidate)
                    or AICCombatUtils.IsWaterAtPosition(Candidate, TargetMob)
                    or AICCombatUtils.IsPathThroughWater(Candidate)
                    or AICCombatUtils.IsPathThroughDeadzone(Candidate)
                    or AICCombat.IsPathThroughBladeGroupDanger(Candidate, TargetMob)
                    or not AICCombatUtils.IsEscapePathClear(Candidate)
                then
                    continue
                end
        
                --// Keep enough space from the threat while avoiding a huge
                --// increase in distance from the primary target.
                local ThreatDistance = AICCombatUtils.GetHorizontalDistance(Candidate, ThreatRoot.Position)
                local TargetDistance = AICCombatUtils.GetHorizontalDistance(Candidate, TargetRoot.Position)
        
                --// Penalize positions that move much farther from the primary target.
                local TargetDistancePenalty = math.max(0, TargetDistance - CurrentTargetDistance) * 0.35
        
                --// Prefer directions closer to directly away from the threat.
                local DirectionPenalty = (1 - math.clamp(AwayDirection:Dot(Direction), -1, 1)) * 2
        
                local Score = TargetDistancePenalty + DirectionPenalty + Index * 0.01
        
                --// The old build tested THREAT_DETECTION_DISTANCE first and then
                --// ENEMY_ATTACK_SAFE_DISTANCE in an elseif with an identical body.
                --// The first condition is a subset of the second, so only the
                --// smaller threshold ever decided anything.
                if ThreatDistance > CONFIG.ENEMY_ATTACK_SAFE_DISTANCE
                    and Score < BestScore
                then
                    BestScore = Score
                    BestPosition = Candidate
                end
            end
        
            return BestPosition
        end
        
        --// Combat Target Validation
        function AICCombat.IsCombatTargetValid(Mob)
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
            if not Mob or not Mob:IsA("Model") then
                return false
            end
        
            if not Mob:IsDescendantOf(workspace) then
                return false
            end
        
            if not RootPart then
                return false
            end
        
            local MobHumanoid = Mob:FindFirstChildOfClass("Humanoid")
            local MobRoot     = Mob:FindFirstChild("HumanoidRootPart")

            if not MobHumanoid or not MobRoot then
                return false
            end

            local EntityName = AICCombat.GetTargetEntityName(Mob)

            if not EntityName or not AICCombat.IsEntityTargeted(EntityName) then
                return false
            end
        
            if MobHumanoid.Health <= 0 then
                return false
            end
        
            local Offset = MobRoot.Position - RootPart.Position
            local Distance = Vector3.new(Offset.X, 0, Offset.Z).Magnitude
        
            if CONFIG.DISTANCE_Y_CALCULATE then
                Distance = Offset.Magnitude
            end
        
            return Distance <= CONFIG.COMBAT_ENGAGE_MAX_DISTANCE
        end
        
        ------------------------------------------------------------------------
        --// AICNav  ::  combat positioning, pathfinding, retreat, patrol
        --// 26 function(s)
        ------------------------------------------------------------------------
        --// Find a short detour when another player is physically blocking the route.
        function AICCombat.GetOtherPlayerDetourPosition(TargetPosition, Goblin)
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
            if not RootPart or not TargetPosition then
                return nil
            end
        
            local Origin = RootPart.Position
            local Direction = TargetPosition - Origin
            if Direction.Magnitude <= 0.01 then
                return nil
            end
        
            local RaycastParams = RaycastParams.new()
            RaycastParams.FilterType = Enum.RaycastFilterType.Exclude
            RaycastParams.FilterDescendantsInstances = {
                Character,
                Goblin,
            }
            if AICCombatUtils.S.DebugFolder then
                table.insert(RaycastParams.FilterDescendantsInstances, AICCombatUtils.S.DebugFolder)
            end
        
            local Hit = workspace:Raycast(Origin, Direction, RaycastParams)
            if not Hit then
                return nil
            end
        
            local Blocker = Hit.Instance and Hit.Instance:FindFirstAncestorOfClass("Model")
            local BlockerPlayer = Blocker and Players:GetPlayerFromCharacter(Blocker)
            if not BlockerPlayer or BlockerPlayer == Player then
                return nil
            end
        
            local BlockerRoot = Blocker:FindFirstChild("HumanoidRootPart")
            if not BlockerRoot then
                return nil
            end
        
            local FlatDirection = Vector3.new(Direction.X, 0, Direction.Z)
            if FlatDirection.Magnitude <= 0.01 then
                return nil
            end
            FlatDirection = FlatDirection.Unit
        
            local Side = Vector3.new(-FlatDirection.Z, 0, FlatDirection.X)
            local DetourDistance = CONFIG.OTHER_PLAYER_DETOUR_DISTANCE
            local Candidates = {
                BlockerRoot.Position + Side * DetourDistance,
                BlockerRoot.Position - Side * DetourDistance,
            }
        
            for _, Candidate in ipairs(Candidates) do
                local GroundCandidate = AICCombatUtils.GetPatrolGroundPosition(Candidate) or Candidate
                if AICCombatUtils.IsInsideFarmArea(GroundCandidate)
                    and not AICCombatUtils.IsInsideFarmDeadzone(GroundCandidate)
                    and not AICCombatUtils.IsWaterAtPosition(GroundCandidate, Goblin)
                    and not AICCombatUtils.IsPathThroughWater(GroundCandidate)
                    and not AICCombatUtils.IsPathThroughDeadzone(GroundCandidate)
                then
                    local ToDetour = GroundCandidate - Origin
                    local DetourHit = workspace:Raycast(Origin, ToDetour, RaycastParams)
                    if not DetourHit then
                        return GroundCandidate
                    end
                end
            end
        
            return nil
        end
        
        --// Get a safe combat position around the Target.
        function AICCombat.AcquireCombatTarget(now)
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
            if not RootPart then
                return nil
            end
        
            if AICCombat.S.ClosestTarget
                and AICCombat.IsTargetLockValid(AICCombat.S.ClosestTarget)
                and now - AICCombat.S.LAST_COMBAT_TARGET_CHECK < CONFIG.COMBAT_TARGET_RECHECK
            then
                return AICCombat.S.ClosestTarget
            end
        
            AICCombat.S.LAST_COMBAT_TARGET_CHECK = now
        
            local Current = AICCombat.S.ClosestTarget
            local Candidate = AICCombat.GetClosestGoblin()
        
            if Current and AICCombat.IsTargetLockValid(Current) then
                local CurrentDistance = AICCombatUtils.GetMobDistance(Current)
                local CandidateDistance = Candidate and AICCombatUtils.GetMobDistance(Candidate) or math.huge
                local CurrentPriority = AICCombat.GetMobPriority(Current) or math.huge
                local CandidatePriority = Candidate and (AICCombat.GetMobPriority(Candidate) or math.huge) or math.huge
        
                local BetterPriority = CandidatePriority < CurrentPriority
                local MeaningfullyCloser =
                    CandidateDistance + CONFIG.COMBAT_STICKY_DISTANCE_BONUS < CurrentDistance
        
                if not BetterPriority and not MeaningfullyCloser then
                    return Current
                end
            end
        
            if Candidate then
                AICCombat.S.COMBAT_TARGET_LOST_SINCE = nil
                AICCombat.S.COMBAT_TARGET_SCORE = AICCombatUtils.GetMobDistance(Candidate)
                return Candidate
            end
        
            if Current and AICCombat.IsTargetLockValid(Current) then
                if not AICCombat.S.COMBAT_TARGET_LOST_SINCE then
                    AICCombat.S.COMBAT_TARGET_LOST_SINCE = now
                end
        
                if now - AICCombat.S.COMBAT_TARGET_LOST_SINCE <= CONFIG.COMBAT_TARGET_GRACE then
                    return Current
                end
            end
        
            AICCombat.S.COMBAT_TARGET_LOST_SINCE = nil
            AICCombat.S.COMBAT_TARGET_SCORE = math.huge
            return nil
        end
        
        --// Get All Living Goblins

        function Module:CreateUI()
            if UIRef.TargetSection then
                UIRef.SafeEnemyRangeSlider = AICUI.AddSettingSlider(
                    UIRef.TargetSection, "Safe Enemy Range", "SAFE_ENEMY_RANGE"
                )
                UIRef.CloseCombatRangeSlider = AICUI.AddSettingSlider(
                    UIRef.TargetSection, "Close Combat Range", "CLOSE_COMBAT_RANGE"
                )
            end
        end

        Module:CreateUI()

        --// Players are targets too, so the picker follows the roster, and a
        --// player who leaves is dropped at once rather than on the next scan.
        Context.Connect(Players.PlayerAdded, function()
            AICCombat.NotifyMobSetChanged("Player")
        end)

        Context.Connect(Players.PlayerRemoving, function(LeavingPlayer)
            local LeavingCharacter = LeavingPlayer.Character

            if LeavingCharacter then
                AICCombat.S.ValidMobs[LeavingCharacter] = nil

                if AICCombat.S.ClosestTarget == LeavingCharacter then
                    AICCombat.S.ClosestTarget = nil
                    AICCombat.ResetTargetReposition()
                end
            end

            task.defer(AICCombat.NotifyMobSetChanged, "Player")
        end)

        AICCombat.S.ExistingMobFolder = workspace:FindFirstChild("Mobs")

        if AICCombat.S.ExistingMobFolder then
            AICCombat.WatchMobFolder(AICCombat.S.ExistingMobFolder)
        end

        Context.Connect(workspace.ChildAdded, function(Child)
            if Child.Name ~= "Mobs" then
                return
            end

            AICCombat.WatchMobFolder(Child)
            AICCombat.NotifyMobSetChanged()
        end)

        Context.Connect(workspace.ChildRemoved, function(Child)
            if Child.Name ~= "Mobs" then
                return
            end

            for _, Connection in AICCombat.S.MobFolderConnections do
                Connection:Disconnect()
            end

            table.clear(AICCombat.S.MobFolderConnections)

            for Mob in AICCombat.S.MobConnections do
                AICCombat.DisconnectMob(Mob)
            end

            table.clear(AICCombat.S.ValidMobs)
            AICCombat.S.ClosestTarget = nil
            AICCombat.NotifyMobSetChanged()
        end)

        return Module
    end,
}
]======],
	["Core/Bootstrap.lua"] = [======[
return {
    Name = "Bootstrap",
    Dependencies = {"Runtime", "ProfileManager", "Components", "ProfileSettings", "Waypoints", "Farmzone", "Deadzone", "DebugVisualizer", "CombatUtils", "Targeting", "Navigation", "Combat", "AutoFarming", "AutoBlock", "AutoPatrol", "ReturnToFarmZone", "AntiAFK"},
    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local Replicated = Services.Replicated
        local StarterGui = Services.StarterGui
        local RunService = Services.RunService
        local UserInputService = Services.UserInputService
        local MarketplaceService = Services.MarketplaceService
        local PathfindingService = Services.PathfindingService
        local HttpService = Services.HttpService
        local Player = Context.Player
        local PlayerGui = Context.PlayerGui
        local CONFIG = Context.CONFIG
        local AICConfig = Context.AICConfig
        local AICProfile = Context.AICProfile
        local AICCombatUtils = Context.AICCombatUtils
        local AICCombat = Context.AICCombat
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local AICDebug = Context.AICDebug
        local Feature = Context.Feature
        local MiningFeature = Context.MiningFeature
        local UI = Context.UI
        local UIRef = Context.UIRef
        local PatrolState = Context.PatrolState
        local NotifyAction = Context.NotifyAction
        local AICPlaceConfig = Runtime:GetPlaceConfig()
        local DEBUG_COLORS = Context.DEBUG_COLORS
        local BasePlaceConfig = Runtime:GetBasePlaceConfig()
        local InputBindableFunction = Runtime:GetInputBindableFunction()
        local FaceOrientation = Runtime:GetFaceOrientation()

        --// Bootstrap / composition root
        --//
        --// Composition root. Creates the window, every control and the debug
        --// visualiser, then restores the last used profile. Nothing here runs
        --// per frame.
        ------------------------------------------------------------------------
        
        --======================================================================
        --// SECTION 3  ::  BOOTSTRAP AND RUNTIME
        --// Everything that actually executes, in its original order.
        --======================================================================
        
        
        --// PlaceConfig, BasePlaceConfig and the default target priority are
        --// resolved in Runtime. Rebuilding them here would hand out new tables
        --// after ProfileManager and the zone modules already hold the old ones.

        AICFeature.updateCharacter()
        
        AICFeature.CreateToggleContainer()
        AICFeature.RegenStamina()
        
        Context.Connect(Player.CharacterAdded, function()
            task.wait()
        
            AICFeature.S.DEATH_COUNT += 1
            CONFIG.CURRENT_WAYPOINT_TARGET = 1
            AICFeature.S.WaypointWaitUntil = nil
            if AICFeature.ResetWaypointLoop then AICFeature.ResetWaypointLoop() end
            AICDebug.ResetDebugWaypoints()
            AICDebug.UpdateDebugWaypointColors()
            AICCombat.S.ClosestTarget = nil
            Runtime:SetInputBindableFunction(nil)
            AICFeature.S.BlockValue = nil
            AICFeature.S.Equipped = false
            AICCombat.S.RETREATING = false
            AICCombat.S.SkillRetreatPosition = nil
            AICCombat.S.LastSkillRetreatTime = 0
            AICCombat.S.SkillThreatUntil = 0
            AICCombat.S.LastSkillSolverTime = 0
            AICFeature.S.LAST_EQUIP_TIME = 0
            PatrolState.PatrolLegsRemaining = 0
            PatrolState.PatrolHeading = nil
            AICCombatUtils.S.StuckSamplePosition = nil
            AICCombatUtils.S.StuckStrikes = 0
            AICCombat.S.LAST_ATTACK_TIME = 0
            AICCombat.S.LAST_SKILL_TIME = 0
            AICCombat.S.LAST_COMBAT_TARGET_CHECK = 0
            AICCombat.S.COMBAT_TARGET_LOST_SINCE = nil
            AICCombat.S.COMBAT_TARGET_SCORE = math.huge
            AICCombat.S.COMBAT_ATTACK_PHASE = 0
            AICCombat.S.COMBAT_NEXT_ATTACK_TIME = 0
            AICCombat.S.COMBAT_NEXT_SKILL_TIME = 0
            AICFeature.S.LAST_CONSUME_TIME = 0
            AICFeature.S.LAST_INTERACTION_TIME = 0
            AICCombatUtils.S.LAST_STUCK_POSITION = nil
            AICFeature.S.FaceAttachment = nil
            Runtime:SetFaceOrientation(nil)
        
            if AICCombatUtils.S.DebugFolder then
                --// Keep the debug instances, but reset their state/colors for the new life.
                for Index, Data in AICDebug.S.DebugWaypointData do
                    if Data.Label then
                        Data.Label.TextColor3 = DEBUG_COLORS.WaypointPending
                    end
                    if Data.Marker then
                        Data.Marker.BackgroundColor3 = DEBUG_COLORS.WaypointPending
                    end
                end
            end
        
            if AICFeature.S.StaminaConnection then
                AICFeature.S.StaminaConnection:Disconnect()
                AICFeature.S.StaminaConnection = nil
            end
        
            table.clear(AICCombat.S.ValidMobs)
            table.clear(AICCombat.S.CombatGroupCache)
            table.clear(AICCombat.S.CombatBladeCache)
            table.clear(AICCombatUtils.S.BladePartCache)
            AICCombat.ClearUnreachableMobs()
        
            task.delay(0.5, function()
                AICFeature.S.Equipped = false
            end)
        
            AICFeature.updateCharacter()
            AICCombat.ResetTargetReposition()
            AICFeature.CreateToggleContainer()
            AICFeature.RegenStamina()
        end)
        
        
        
        --//==============================================================
        --// Utility UI
        --//==============================================================
        
        --UI:SetTheme({
        --    Background      = CONFIG.UI_PANEL,
        --    BackgroundLight = CONFIG.UI_SURFACE,
        --    Panel           = CONFIG.UI_SURFACE,
        --    PanelLight      = CONFIG.UI_HOVER,
        --    PanelHover      = Color3.fromRGB(48, 50, 60),
        --    Element         = CONFIG.UI_SURFACE,
        --    ElementHover    = CONFIG.UI_HOVER,
        --    Text            = CONFIG.UI_TEXT,
        --    TextSecondary   = Color3.fromRGB(190, 193, 204),
        --    TextMuted       = CONFIG.UI_MUTED,
        --    Cyan            = CONFIG.UI_ACCENT,
        --    CyanDark        = Color3.fromRGB(80, 90, 190),
        --    CyanDim         = Color3.fromRGB(150, 160, 255),
        --    White           = CONFIG.UI_TEXT,
        --    Border          = CONFIG.UI_BORDER,
        --    BorderDim       = Color3.fromRGB(45, 48, 58),
        --    Danger          = Color3.fromRGB(255, 65, 65),
        --    Warning         = Color3.fromRGB(255, 180, 0),
        --    Black           = Color3.fromRGB(10, 10, 14),
        --})
        
        --// Feature toggles
        Feature.ResetStats.Enabled = true
        
        --// Priority component
        UIRef.PriorityComponent = UIRef.TargetSection:AddPriority(
            "Enemy Priority",
            CONFIG.TARGET_ENTITY_PRIORITY
        )
        
        -- Keep CONFIG and the Utils priority component on the same table.
        CONFIG.TARGET_ENTITY_PRIORITY = UIRef.PriorityComponent.Priority
        
        --// Capture the stock methods before the overrides below replace them.
        AICUI.S.OriginalPriorityAdd      = UIRef.PriorityComponent.Add
        AICUI.S.OriginalPriorityRemove   = UIRef.PriorityComponent.Remove
        AICUI.S.OriginalPriorityMoveUp   = UIRef.PriorityComponent.MoveUp
        AICUI.S.OriginalPriorityMoveDown = UIRef.PriorityComponent.MoveDown
        
        function UIRef.PriorityComponent:Add(EntityName)
            if not AICProfile.S.ActiveProfileName then
                return false
            end
        
            local Changed = AICUI.S.OriginalPriorityAdd(self, EntityName)
        
            if Changed then
                AICUI.SyncPriorityState(true)
            end
        
            return Changed
        end
        
        function UIRef.PriorityComponent:Remove(EntityName)
            if not AICProfile.S.ActiveProfileName then
                return false
            end
        
            local Changed = AICUI.S.OriginalPriorityRemove(self, EntityName)
        
            if Changed then
                AICUI.SyncPriorityState(true)
            end
        
            return Changed
        end
        
        function UIRef.PriorityComponent:MoveUp(EntityName)
            if not AICProfile.S.ActiveProfileName then
                return
            end
        
            AICUI.S.OriginalPriorityMoveUp(self, EntityName)
            AICUI.SyncPriorityState(true)
        end
        
        function UIRef.PriorityComponent:MoveDown(EntityName)
            if not AICProfile.S.ActiveProfileName then
                return
            end
        
            AICUI.S.OriginalPriorityMoveDown(self, EntityName)
            AICUI.SyncPriorityState(true)
        end
        
        AICUI.S.AddPriorityTarget = function(EntityName)
            if not EntityName or EntityName == "" or AICUI.S.TargetPickerPlaceholders[EntityName] then
                return
            end
        
            if AICCombat.IsEntityInPriority(EntityName) then
                return
            end

            --// A player entry is accepted only while that player is still in
            --// the server, and never the local player.
            if AICCombat.IsPlayerTargetName(EntityName) then
                local OtherPlayer = Players:FindFirstChild(string.sub(EntityName, 2))

                if not OtherPlayer
                    or not OtherPlayer:IsA("Player")
                    or not AICCombat.IsTargetablePlayer(OtherPlayer)
                then
                    NotifyAction("Target Priority", "Player is not in this server")
                    AICUI.RefreshTargetDropdown()
                    return
                end
            end

            UIRef.PriorityComponent:Add(EntityName)
        end
        
        UIRef.TargetRefreshButton = UIRef.TargetSection:AddButton{
            Name = "Refresh Detected Targets",
            Callback = function()
                AICUI.RefreshTargetDropdown()
            end,
        }

        --// UI font, picked in Configuration and kept in the global file.
        if UI.SetFont then
            if CONFIG.UI_FONT ~= "" and not UI:SetFont(CONFIG.UI_FONT) then
                CONFIG.UI_FONT = ""
            end

            UI.OnFontChanged = function(Name)
                CONFIG.UI_FONT = Name
                AICProfile.WriteGlobalStore()
            end
        end

        --// Theme colours, also kept in the global file: only the keys that
        --// differ from the built-in theme are saved.
        if UI.SetTheme and UI._DefaultTheme then
            local Saved = {}

            for Key, Hex in pairs(CONFIG.UI_THEME) do
                local Ok, Color = pcall(Color3.fromHex, Hex)

                if Ok and UI.Theme[Key] ~= nil then
                    Saved[Key] = Color
                end
            end

            if next(Saved) then
                UI:SetTheme(Saved)
            end

            UI.OnThemeChanged = function(Theme)
                local Changed = {}

                for Key, Color in pairs(Theme) do
                    local Default = UI._DefaultTheme[Key]

                    if typeof(Color) == "Color3" and (typeof(Default) ~= "Color3" or Color:ToHex() ~= Default:ToHex()) then
                        Changed[Key] = Color:ToHex()
                    end
                end

                CONFIG.UI_THEME = Changed
                AICProfile.WriteGlobalStore()
            end
        end

        --// UI text scale, also kept in the global file.
        if UI.SetTextScale then
            if CONFIG.UI_TEXT_SCALE ~= 1 then
                CONFIG.UI_TEXT_SCALE = UI:SetTextScale(CONFIG.UI_TEXT_SCALE)
            end

            UI.OnTextScaleChanged = function(Scale)
                if CONFIG.UI_TEXT_SCALE == Scale then
                    return
                end

                CONFIG.UI_TEXT_SCALE = Scale
                AICProfile.WriteGlobalStore()
            end
        end

        --// Pinned items
        --// Lives outside the tabs so the panel can be dragged or popped out.
        --// One optional panel must never keep the rest of the menu down, so a
        --// failure here is reported and skipped rather than raised.
        local PinsOk, PinsError = pcall(function()
            UIRef.PinPanel = UI:AddPin("Pinned Items")

            --// Pins are global: restore them from their own file before any
            --// profile loads, and write every change back there.
            local StoredPinned = AICProfile.ReadPinnedState()

            if StoredPinned then
                AICProfile.S.HasGlobalPinnedState = true
                CONFIG.PINNED_STATE = StoredPinned
                UIRef.PinPanel:SetState(StoredPinned)
            end

            UIRef.PinnedSection = UIRef.StatusTab:AddSection{ Title = "Pinned Items" }

            --// The only way to show the panel again once its × closed it.
            UIRef.PinnedVisibleToggle = UIRef.PinnedSection:AddToggle{
                Name = "Show Pinned Items",
                Default = UIRef.PinPanel.Visible,
                Callback = function(Value)
                    UIRef.PinPanel:SetVisible(Value)
                    CONFIG.PINNED_STATE = UIRef.PinPanel:GetState()
                    AICProfile.QueuePinnedSave()
                end,
            }

            UIRef.PinPanel.OnChanged = function()
                CONFIG.PINNED_STATE = UIRef.PinPanel:GetState()
                UIRef.PinnedVisibleToggle:Set(UIRef.PinPanel.Visible, false)
                AICProfile.QueuePinnedSave()
                AICProfile.QueueProfileSave()
            end

            UIRef.PinnedSection:AddButton{
                Name = "Reset Pinned Items Position",
                Callback = function()
                    UIRef.PinPanel:ResetPosition()
                    NotifyAction("Pinned Items", "Position reset")
                end,
            }

            task.spawn(function()
                local PlayerStats = Player:WaitForChild("PlayerStats", 30)
                local Inventory = PlayerStats and PlayerStats:WaitForChild("Inventory", 30)

                if Inventory then
                    UI:BindPinToValue(UIRef.PinPanel, Inventory)
                end
            end)
        end)

        if not PinsOk then
            warn("[AIC] Pinned items panel unavailable: " .. tostring(PinsError))
            UIRef.PinPanel = nil
        end

        --// Breaks ties between mobs of equal priority. Disabled keeps nearest first.
        UIRef.TargetTypeDropdown = UIRef.TargetSection:AddDropdown{
            Name = "Target Type",
            Options = { "Disabled", "Highest HP", "Lowest HP" },
            Callback = function(Value)
                CONFIG.TARGET_HP_MODE = tostring(Value or "Disabled")
                AICCombat.ResetTargetState()
                AICProfile.SaveActiveProfile()
            end,
        }
        
        UIRef.TargetTypeDropdown:Set(tostring(CONFIG.TARGET_HP_MODE or "Disabled"), false)
        
        
        AICUI.RefreshTargetDropdown()
        
        AICUI.updateFeatureButtons()
        
        return {Name = "Bootstrap"}
    end,
}
]======],
	["Core/GuiClick.lua"] = [======[
-- GuiClick presses a GuiButton the way an executor allows. Shared by
-- AutoBlockConfirm (Roblox's Block dialog) and AutoSmithing (the strike
-- button of the smithing minigame).
--
-- Methods, each tried only when the executor provides it:
--   firesignal / getconnections  fire the button's handlers directly,
--                                instantly and without moving the cursor
--   VirtualInputManager          a synthetic mouse click on the button
--   mouse                        moves the real cursor, clicks, moves back
return {
    Name = "GuiClick",
    Dependencies = {},

    Start = function(Context)
        local GuiService = game:GetService("GuiService")
        local UserInputService = game:GetService("UserInputService")

        local CLICK_HOLD_SECONDS = 0.05

        local CloneReference = type(cloneref) == "function" and cloneref or function(Instance)
            return Instance
        end

        local HasVirtualInput, VirtualInputManager = pcall(function()
            return CloneReference(game:GetService("VirtualInputManager"))
        end)

        if not HasVirtualInput then
            VirtualInputManager = nil
        end

        local GuiClick = { Name = "GuiClick" }

        --// Drawn and big enough to click: every ancestor up to its
        --// ScreenGui is visible and that ScreenGui is enabled.
        function GuiClick.IsOnScreen(Gui)
            if not Gui or not Gui.Parent then
                return false
            end

            if Gui.AbsoluteSize.X < 1 or Gui.AbsoluteSize.Y < 1 then
                return false
            end

            local Node = Gui

            while Node do
                if Node:IsA("GuiObject") and not Node.Visible then
                    return false
                end

                if Node:IsA("LayerCollector") then
                    return Node.Enabled
                end

                Node = Node.Parent
            end

            return false
        end

        local function FireConnections(Signal)
            if type(getconnections) ~= "function" then
                return false
            end

            local Ok, Connections = pcall(getconnections, Signal)

            if not Ok or type(Connections) ~= "table" then
                return false
            end

            local Fired = false

            for _, Connection in ipairs(Connections) do
                if pcall(function()
                    Connection:Fire()
                end) then
                    Fired = true
                end
            end

            return Fired
        end

        local function FireSignal(Signal)
            if type(firesignal) ~= "function" then
                return false
            end

            return (pcall(firesignal, Signal))
        end

        --// Screen-space centre of a button, including the top bar inset when
        --// its ScreenGui uses it.
        local function GetButtonCenter(Button)
            local Center = Button.AbsolutePosition + Button.AbsoluteSize / 2
            local ScreenGui = Button:FindFirstAncestorWhichIsA("ScreenGui")

            if not (ScreenGui and ScreenGui.IgnoreGuiInset) then
                Center += GuiService:GetGuiInset()
            end

            return Center
        end

        local function ClickWithVirtualInput(Button)
            if not VirtualInputManager then
                return false
            end

            local Center = GetButtonCenter(Button)

            return (pcall(function()
                VirtualInputManager:SendMouseButtonEvent(Center.X, Center.Y, 0, true, game, 0)
                task.wait(CLICK_HOLD_SECONDS)
                VirtualInputManager:SendMouseButtonEvent(Center.X, Center.Y, 0, false, game, 0)
            end))
        end

        local function ClickWithRealMouse(Button)
            if type(mousemoveabs) ~= "function" or type(mouse1click) ~= "function" then
                return false
            end

            local Center = GetButtonCenter(Button)
            local Previous = UserInputService:GetMouseLocation()

            return (pcall(function()
                mousemoveabs(Center.X, Center.Y)
                task.wait(CLICK_HOLD_SECONDS)
                mouse1click()
                task.wait(CLICK_HOLD_SECONDS)
                mousemoveabs(Previous.X, Previous.Y)
            end))
        end

        --// Which of the button's signals the direct methods fire, first that
        --// works. firesignal "works" even with nothing listening, so a
        --// caller that knows the game listens to one signal passes only it.
        local DEFAULT_SIGNALS = { "Activated", "MouseButton1Click" }

        local function FireFirst(Fire, Button, Signals)
            for _, SignalName in ipairs(Signals or DEFAULT_SIGNALS) do
                if Fire(Button[SignalName]) then
                    return true
                end
            end

            return false
        end

        --// In default order. Each Click(Button, Signals) returns true when it
        --// could send.
        GuiClick.Methods = {
            {
                Name = "getconnections",
                Click = function(Button, Signals)
                    return FireFirst(FireConnections, Button, Signals)
                end,
            },
            {
                Name = "firesignal",
                Click = function(Button, Signals)
                    return FireFirst(FireSignal, Button, Signals)
                end,
            },
            { Name = "VirtualInputManager", Click = ClickWithVirtualInput },
            { Name = "mouse", Click = ClickWithRealMouse },
        }

        --// The methods with Preferred (a method name, usually the one that
        --// worked last) moved to the front.
        function GuiClick.GetOrderedMethods(Preferred)
            local Ordered = {}

            for _, Method in ipairs(GuiClick.Methods) do
                if Method.Name == Preferred then
                    table.insert(Ordered, 1, Method)
                else
                    table.insert(Ordered, Method)
                end
            end

            return Ordered
        end

        --// Clicks with the first method that can send. Returns its name, or
        --// nil when none could. The caller checks whether it took effect.
        function GuiClick.Click(Button, Preferred, Signals)
            for _, Method in ipairs(GuiClick.GetOrderedMethods(Preferred)) do
                if Method.Click(Button, Signals) then
                    return Method.Name
                end
            end

            return nil
        end

        return GuiClick
    end,
}
